y damage will break the effect.","\"Thro mo mo tar!\""},sk="Schematic: EZ-Thro Bronze Mortar (skill 190)",m="4 x Bronze Tube , 1 x Iron Strut , 4 x Heavy Blasting Powder , 4 x Medium Leather , 1 x EZ-Thro Fireproof Fuse",li=S[5],sp={"ELE"}},["shaman-1441"]={n="Goblin Land Mine",id=4395,k="c",q=1,s="Explosives",p="Engineering",il=39,a="Engineering · Schematic: Goblin Land Mine (skill 195)",w={ELE=S[4]},tt={S[456],"Requires Engineering (195)","Use: Places the Goblin Land Mine on the ground. It will explode for 394 to 506 Fire damage the next time a hostile creature passes near it. The mine has a duration of 1 min."},sk="Schematic: Goblin Land Mine (skill 195)",m="3 x Heavy Blasting Powder , 2 x Iron Bar , 1 x Gyrochronatom",li=S[5],sp={"ELE"}},["shaman-1442"]={n="Gnomish Shrink Ray",id=10716,k="c",q=1,s=S[261],p="Engineering",il=41,a=S[39],w={ENH=S[4]},tt={S[271],S[8],"Trinket",S[367],"Use: Shrinks the target reducing their attack power by 250. Thats what it usually does anyway....."},sk=S[11],m="1 x Mithril Tube , 1 x Unstable Trigger , 4 x Mithril Bar , 4 x Flask of Mojo , 2 x Jade",li=S[5],sp={"ENH"}},["shaman-1443"]={n="Goblin Construction Helmet",id=10543,k="c",q=2,s="Cloth",p="Engineering",il=41,a=S[39],w={ELE=S[4]},tt={S[271],S[9],"Head Cloth","44 Armor","+15 Fire Resistance",S[367],"Use: Absorbs 300 to 500 Fire damage. Lasts 1 min."},sk=S[11],m="8 x Mithril Bar , 1 x Citrine , 4 x Elemental Fire",li=S[5],sp={"ELE"}},["shaman-1444"]={n="The Big One",id=10586,k="c",q=1,s="Explosives",p="Engineering",il=45,a=S[39],w={ELE=S[4]},tt={S[128],S[625],"Use: Inflicts 340 to 460 Fire damage and stuns targets for 5 sec in a 10 yard radius. Any damage will break the effect."},sk=S[11],m="1 x Mithril Casing , 1 x Goblin Rocket Fuel , 6 x Solid Dynamite , 1 x Unstable Trigger",li=S[5],sp={"ELE"}},["shaman-1445"]={n="Dense Dynamite",id=18641,k="c",q=1,s="Explosives",p="Engineering",il=45,a=S[39],w={ELE=S[4]},tt={S[128],"Requires Engineering (250)","Use: Inflicts 340 to 460 Fire damage in a 5 yard radius."},sk=S[11],m="2 x Dense Blasting Powder , 3 x Runecloth",li=S[5],sp={"ELE"}},["shaman-1446"]={n="Gnomish Mind Control Cap",id=10726,k="c",q=2,s="Cloth",p="Engineering",il=47,a=S[39],w={ELE=S[4],RESTO=S[4]},tt={S[186],S[8],"Head Cloth","50 Armor","+14 Spirit",S[626],"Use: Engage in mental combat with a humanoid target to try and control their mind. If all works well, you will control the mind of the target for 20 sec ....."},sk=S[11],m="10 x Mithril Bar , 4 x Truesilver Bar , 1 x Gold Power Core , 2 x Star Ruby , 4 x Shamanweave Cloth",li=S[5],sp={"ELE","RESTO"}},["shaman-1447"]={n="SAF-T Clever Dynamite",id=260814,k="c",q=1,s="Explosives",p="Engineering",rl=1,il=50,a="Engineering · Schematic: SAF-T Clever Dynamite (skill 275)",w={ELE=S[4]},tt={S[178],S[172],"Use: Inflicts 340 to 460 Fire damage in a 5 yd radius.","\"SAF-T isn't dense. It's clever!\""},sk="Schematic: SAF-T Clever Dynamite (skill 275)",m="2 x Dense Blasting Powder , 3 x Runecloth , 1 x SAF-T Tube",li=S[5],sp={"ELE"}},["shaman-1448"]={n="Major Recombobulator",id=18637,k="c",q=2,s=S[261],p="Engineering",il=55,a="Engineering · Schematic: Major Recombobulator (skill 275)",w={ELE=S[4],RESTO=S[4]},tt={S[57],"Trinket",S[627],"Use: Dispels Polymorph effects on a friendly target. Also restores 500 to 832 Health and 228 to 380 Mana."},sk="Schematic: Major Recombobulator (skill 275)",m="2 x Thorium Tube , 1 x Truesilver Transformer , 2 x Runecloth",li=S[5],sp={"ELE","RESTO"}}},quests={["important heirlooms"]={c=S[184],x=-4810.9,y=-961.8,w="Ironforge",q="Important Heirlooms",npc="Thom Filch",k="giver"},["the restless dead"]={c=S[184],x=-4825.7,y=-972.9,w="Ironforge",q="The Restless Dead",npc="Afadra Dunwall",k="giver"},["old ironforge incursion"]={c=S[184],x=-5794.5,y=-1389.3,w="Dun Morogh",q="Old Ironforge Incursion",npc="Earthseer Farsen",k="giver"},["an ancient grudge"]={q="An Ancient Grudge",npc="Ghostly Attendant",k="dungeon",d="hall of thanes",note=S[365]},["a frightened request"]={c=S[184],x=468.3,y=1585.2,w=S[841],q="A Frightened Request",npc="Tabitha Heartweaver",k="giver"},["abominable creatures"]={q="Abominable Creatures",npc="Captain Truman",k="dungeon",d="ruins of lordaeron",note=S[365]},["bloodied insignia"]={c=S[184],x=-8954.9,y=524,w=S[600],q="Bloodied Insignia",npc="General Marcus Jonathan (turn-in)",k="giver",note="This quest starts from an item drop; the pin is where you hand it in."},["light's justice"]={c=S[184],x=1299.3,y=322.5,w="Undercity",q="Light's Justice",npc="Morbin Lightbane",k="giver"},["the new plague"]={c=S[184],x=1427.3,y=430,w="Undercity",q="The New Plague",npc="Theodore Griffs",k="giver"},["the wrath of rath'mael"]={c=S[184],x=2024,y=87.1,w="Tirisfal Glades",q="The Wrath of Rath'mael",npc="Deathguard Kristof",k="giver"},["collecting memories"]={c=S[184],x=-8241.4,y=590.1,w=S[600],q=S[777],npc="Wilder Thistlenettle",k="giver"},["underground assault"]={c=S[184],x=-8139.5,y=760.3,w=S[600],q=S[778],npc=S[842],k="giver"},["gyrodrillmatic excavationators"]={c=S[184],x=-8139.5,y=760.3,w=S[600],q=S[462],npc=S[842],k="giver"},["red silk bandanas"]={c=S[184],x=-10506,y=1035.7,w="Westfall",q=S[643],npc="Scout Riell",k="giver"},["the defias brotherhood"]={c=S[184],x=-10506,y=1049.7,w="Westfall",q=S[717],npc="Gryan Stoutmantle",k="giver"},["deathstalkers in shadowfang"]={c=S[184],x=524.3,y=1627.2,w=S[841],q=S[603],npc="High Executor Hadrec",k="giver"},["the book of ur"]={c=S[184],x=1538.7,y=360.9,w="Undercity",q=S[890],npc="Keeper Bel'dugur",k="giver",note="Position is approximate."},["deviate eradication"]={q="Deviate Eradication",npc="Ebru",k="dungeon",d="wailing caverns",note="Ebru stands in the alcove above the cavern entrance; the pin is the dungeon entrance."},["leaders of the fang"]={c="kalimdor",x=-1065.7,y=-270.3,w=S[910],q="Leaders of the Fang",npc="Nara Wildmane",k="giver"},serpentbloom={c="kalimdor",x=-987.8,y=282.9,w=S[910],q=S[920],npc="Apothecary Zamah",k="giver"},["researching the corruption"]={c="kalimdor",x=6455.7,y=426.5,w="Darkshore",q=S[629],npc="Gershala Nightwhisper",k="giver"},["twilight falls"]={c="kalimdor",x=10073.2,y=2354.2,w="Darnassus",q=S[891],npc="Argent Guard Manados",k="giver"},["blackfathom villainy"]={q=S[744],npc="Argent Guard Thaelrid",k="dungeon",d="blackfathom deeps",note="The quest starts inside the dungeon, so the pin is the entrance."},["the power to destroy..."]={c=S[184],x=1286.5,y=334,w="Undercity",q=S[685],npc="Varimathras",k="giver"},["returning the lost satchel"]={q="Returning the Lost Satchel",npc="Maur Grimtotem",k="dungeon",d="ragefire chasm",note="Maur is inside the dungeon, so the pin is the entrance."},["the orb of soran'ruk"]={c="kalimdor",x=-2252.1,y=-2362.7,w="The Barrens",q="The Orb of Soran'ruk",npc="Doan Karhan",k="giver",note=S[761]},["the completed robe"]={c="kalimdor",x=-779.2,y=-3700.3,w="The Barrens",q="The Completed Robe",npc="Menara Voidrender",k="giver",note=S[761]},["past due"]={c=S[184],x=331.5,y=520.1,w="Alterac Mountains",q="Past Due",npc="Magus Olvek",k="giver"},["vorrel's revenge"]={q="Vorrel's Revenge",npc="Vorrel Sengutz",k="dungeon",d="scarlet monastery - graveyard",note="Vorrel is inside the dungeon, so the pin is the entrance."},["the night watch"]={c=S[184],x=-10559.1,y=-1148.5,w="Duskwood",q="The Night Watch",npc="Commander Althea Ebonlocke",k="giver",note="Start of the Night Watch quest chain, in Darkshire."},["the undermarket"]={c=S[184],x=-7206.7,y=-1233.3,w="Searing Gorge",q="The Undermarket",npc="Nilith Lokrav",k="giver"}},specs={{id="elemental",name="Elemental",token="ELE",title="Elemental | WoW Forever Shaman Field Guide",nav={{id="overview",x=S[767]},{id="journey",x=S[560]},{id="talents",x=S[484]},{id="stats",x=S[608]},{id="combat",x=S[609]},{id="macros",x=S[610]},{id="dungeons",x=S[540]},{id="professions",x=S[561]},{id="crafting",x=S[549]},{id="questgear",x=S[531]},{id=S[483],x=S[702]}},asideNote=S[68],talentString="5500331021011351054000000000000000053020001",ranks={{tree="Elemental",name="Convection",r=5,max=5},{tree="Elemental",name="Concussion",r=5,max=5},{tree="Elemental",name="Elemental Alacrity",r=3,max=3},{tree="Elemental",name="Call of Flame",r=3,max=3},{tree="Elemental",name=S[879],r=1,max=1},{tree="Elemental",name="Trial by Fire",r=2,max=2},{tree="Elemental",name="Eye of the Storm",r=1,max=3},{tree="Elemental",name="Elemental Reach",r=1,max=2},{tree="Elemental",name="Call of Thunder",r=1,max=1},{tree="Elemental",name="Lightning Overload",r=3,max=3},{tree="Elemental",name="Elemental Fury",r=5,max=5},{tree="Elemental",name=S[645],r=1,max=1},{tree="Enhancement",name=S[611],r=5,max=5},{tree="Enhancement",name=S[593],r=4,max=5},{tree="Restoration",name="Tidal Focus",r=5,max=5},{tree="Restoration",name="Mindfulness",r=3,max=3},{tree="Restoration",name="Totemic Focus",r=2,max=5},{tree="Restoration",name=S[819],r=1,max=1}},order={},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[532]},{t="h1",x="Elemental",sub=S[612]},{t="p",s="lede",x="Build reliable ranged pressure with Lightning Bolt and Flame Shock, then use Lightning Mastery and fire-totem area damage when the encounter allows."},{t="pills",list={S[538],S[562]}},{t="anchor",id="journey"},{t="kicker",x=S[768]},{t="h2",x=S[452]},{t="p",x=S[66]},{t="p",s="level",x="1–19 · Cast from a safe distance"},{t="p",x="Train Lightning Bolt and utility ranks, start pulls from range and keep room to retreat. Use melee only when a low-health enemy can be finished cheaply. Carry drinking water and avoid spending your entire mana pool on damage when a heal may be needed."},{t="p",s="level",x="20–39 · Develop the spell toolkit"},{t="p",x="Build toward the selected Elemental damage, casting and control talents while respecting the calculator’s gates. Earthbind becomes an additional control tool with Earthbound. Keep Flame Shock on enemies that live long enough and fill with Lightning Bolt; Call of Thunder adds critical strike chance to Lightning Bolt and Chain Lightning. Chain Lightning joins the trained toolkit later; check nearby enemies before casting it."},{t="p",s="level",x="40–60 · Complete damage and sustain"},{t="p",x="Finish the Elemental package and the nine Enhancement and eleven Restoration support points. Thundering Strikes and Ancestral Knowledge support casting; Tidal Focus, Mindfulness, Totemic Focus and Water Shield add hit, mana recovery and cheaper totems."},{t="anchor",id="talents"},{t="kicker",x=S[485]},{t="h2",x=S[538]},{t="p",x="Tree order: Elemental / Enhancement / Restoration. These 51 points are entered on the Standards.gg talent calculator and checked against the launch talent trees for totals, maximum ranks, tier gates and prerequisites. Changes made inside the calculator do not rewrite this guide."},{t="widget",w="talents"},{t="h4",s="summary",x=S[541]},{t="widget",w="ranks"},{t="p",s="notice",x="Your build contains 31 Elemental, 9 Enhancement and 11 Restoration points. It does not learn Stormstrike, Shamanistic Focus or Nature’s Swiftness and takes no Natural Grace, so threat management remains important."},{t="anchor",id="stats"},{t="kicker",x=S[613]},{t="h2",x=S[509]},{t="p",x="Elemental wants spell damage first, then hit and critical strike. Intellect and mana per 5 keep you casting through long fights."},{t="h3",x=S[734]},{t="stat",i=1,b="Spell damage",x=S[557]},{t="stat",i=2,b="Intellect",x=S[793]},{t="stat",i=3,b="Stamina",x=""},{t="stat",i=4,b="Spirit",x=S[588]},{t="stat",i=5,b="Strength",x="only while you still melee early on"},{t="p",s="small",x="If you level as Enhancement first, keep useful Intellect and spell damage pieces for the switch around level 40."},{t="h3",x="At level 60"},{t="stat",i=1,b="Spell power",x=S[557]},{t="stat",i=2,b="Hit chance",x="to 17%"},{t="stat",i=3,b=S[703],x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="p",s="small",x="Spell penetration and haste are strong extras when an item offers them; balance them against Intellect and Spirit so you do not run out of mana."},{t="p",s="notice",x="Spell hit cap: 17% against raid bosses (level 63), 4% against enemies of your own level. The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[510]},{t="h2",x=S[550]},{t="p",x=S[81]},{t="h4",x="Set range and useful totems"},{t="p",x="Start from a safe casting position. Select totems for the party and encounter, rather than automatically dropping four for every quest enemy. Maintain enough mana to interrupt, cleanse or heal. Earthbound is useful control but does not make every boss rootable."},{t="h4",x="Keep Flame Shock ticking"},{t="p",x="On a target that will live long enough, apply Flame Shock and refresh it when it falls off. Your shocks share a cooldown, so keep Earth Shock free when an enemy caster needs interrupting."},{t="h4",x="Fill with Lightning Bolt"},{t="p",x="Use Lightning Bolt as your repeatable ranged cast. Lightning Overload is a passive proc; you do not press a separate ability to trigger it. Favor safe, uninterrupted casts over standing in dangerous ground effects. Eye of the Storm (1/3) gives some protection from pushback."},{t="h4",x="Match cleave to the pull"},{t="p",x="Chain Lightning is useful when its jumps are safe. Fire Nova erupts from your active fire totem; placement matters. Trial by Fire supports the area toolkit, but mana and crowd control still limit when it is worth using. Move the totems if the pack leaves their range."},{t="h4",x="Plan the Lightning Mastery window"},{t="p",x="Use Lightning Mastery when the target will survive and you can cast through its 15 seconds: it removes Chain Lightning’s cooldown and cuts 0.5 seconds from Lightning Bolt’s cast time. Line it up with racials and trinkets, and avoid emptying your mana merely because the button is available. Use Earth Shock to stop a dangerous cast, even when that interrupts a damage sequence."},{t="abil",names={S[898],"Flame Shock","Chain Lightning","Fire Nova",S[645]}},{t="h3",x=S[646]},{t="p",x="Compare spell damage that affects Nature and Fire, useful spell hit, Intellect, critical chance and mana recovery. A Nature-only piece supports your Lightning spells but not Flame Shock or your fire totems. Tidal Focus is selected at 5/5; evaluate its hit contribution before adding more. Melee weapon DPS is not a casting stat."},{t="p",x=S[64]},{t="h3",x=S[504]},{t="p",x=S[56]},{t="p",x=S[52]},{t="p",x=S[124]},{t="anchor",id="macros"},{t="kicker",x=S[614]},{t="h2",x=S[424]},{t="p",x=S[59]},{t="p",s="notice",x=S[40]},{t="macro",n=S[551],x=S[126],code=S[201]},{t="macro",n=S[583],x=S[120],code=S[175]},{t="macro",n=S[594],x=S[113],code=S[199]},{t="macro",n=S[704],x=S[122],code=S[266]},{t="macro",n=S[563],x=S[121],code=S[230]},{t="macro",n=S[564],x=S[155],code=S[207]},{t="macro",n=S[552],x=S[247],code=S[202]},{t="macro",n=S[542],x=S[158],code=S[179]},{t="macro",n=S[565],x=S[94],code=S[173]},{t="macro",n=S[505],x=S[129],code=S[267]},{t="macro",n=S[615],x=S[160],code=S[342]},{t="macro",n=S[469],x=S[115],code=S[225]},{t="macro",n="Chain Lightning / Shift Flame Shock",x="Hold Shift to apply Flame Shock; otherwise cast Chain Lightning. The macro does not check the debuff or cast both spells through one global cooldown.",code="#showtooltip\n/cast [mod:shift,harm,nodead] Flame Shock; [harm,nodead] Chain Lightning"},{t="macro",n=S[645],x="Keep your selected damage cooldown on a deliberate key. Follow with the damaging spell appropriate for the encounter; no automated rotation is implied.",code="#showtooltip Lightning Mastery\n/cast Lightning Mastery"},{t="macro",n="Mouseover Lightning Bolt",x="Cast at a living hostile mouseover, otherwise your hostile target. It uses your learned spell rank without changing targets.",code="#showtooltip Lightning Bolt\n/cast [@mouseover,harm,nodead][harm,nodead] Lightning Bolt"},{t="p",s="small",x=S[256]},{t="anchor",id="dungeons"},{t="kicker",x=S[705]},{t="h2",x=S[474]},{t="p",x=S[60]},{t="widget",w="rarity"},{t="p",s="notice",x=S[46]},{t="p",s="notice",x=S[74]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[511]},{t="h2",x=S[470]},{t="p",x=S[61]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[543]},{t="h2",x=S[453]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[512]},{t="h2",x=S[420]},{t="p",x=S[41]},{t="widget",w="quest"},{t="anchor",id=S[483]},{t="kicker",x=S[706]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[91]}}},{id="enhancement",name="Enhancement",token="ENH",title="Enhancement | WoW Forever Shaman Field Guide",nav={{id="overview",x=S[767]},{id="journey",x=S[560]},{id="talents",x=S[484]},{id="stats",x=S[608]},{id="combat",x=S[609]},{id="macros",x=S[610]},{id="dungeons",x=S[540]},{id="professions",x=S[561]},{id="crafting",x=S[549]},{id="questgear",x=S[531]},{id=S[483],x=S[702]}},asideNote=S[68],talentString="053303102000000005303031005101225102",ranks={{tree="Elemental",name="Concussion",r=5,max=5},{tree="Elemental",name="Elemental Devastation",r=3,max=3},{tree="Elemental",name="Reverberation",r=2,max=5},{tree="Elemental",name=S[879],r=1,max=1},{tree="Enhancement",name=S[611],r=5,max=5},{tree="Enhancement",name=S[593],r=3,max=5},{tree="Enhancement",name="Mental Dexterity",r=3,max=3},{tree="Enhancement",name="Elemental Weapons",r=3,max=3},{tree="Enhancement",name="Shamanistic Focus",r=1,max=1},{tree="Enhancement",name="Flurry",r=5,max=5},{tree="Enhancement",name="Stormstrike",r=1,max=1},{tree="Enhancement",name="Spirit Weapons",r=1,max=1},{tree="Enhancement",name="Mental Quickness",r=2,max=2},{tree="Enhancement",name="Improved Stormstrike",r=2,max=2},{tree="Enhancement",name=S[861],r=5,max=5},{tree="Enhancement",name=S[595],r=1,max=1},{tree="Restoration",name="Tidal Focus",r=5,max=5},{tree="Restoration",name="Mindfulness",r=3,max=3}},order={},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[532]},{t="p",s="legend",x="|cff71d5ffBlue text was updated for the WoW Forever hotfixes up to 10 November and is awaiting final review.|r"},{t="h1",x="Enhancement",sub=S[612]},{t="p",s="lede",x="Turn melee uptime into Maelstrom-powered Lightning Bolts, use Stormstrike deliberately, and support the group with well-placed totems."},{t="pills",list={S[539],S[562]}},{t="anchor",id="journey"},{t="kicker",x=S[768]},{t="h2",x=S[452]},{t="p",x=S[66]},{t="p",s="level",x="1–19 · Weapon and mana foundations"},{t="p",x="Keep your weapon skill and trained ranks current. Pull with Lightning Bolt when distance allows, then let melee swings finish economical kills. Heal between pulls before committing to another enemy. Begin the Enhancement investment toward your melee and Intellect synergies; reserve mana for a heal or an interrupt."},{t="p",s="level",x="20–39 · Build the melee engine"},{t="p",x="Develop Shamanistic Focus, Stormstrike and Flurry as their gates open. Ghost Wolf stays a travel tool: no PvE Shaman build takes Improved Ghost Wolf. Set useful totems for durable fights, relocate them as the fight moves, and avoid spending a full setup on every short-lived target."},{t="p",s="level",x="40–60 · Finish the hybrid"},{t="p",x="Complete Maelstrom Weapon and Rage of the Farseer, then finish the selected Elemental and Restoration support. Mail becomes available at 40; compare stats rather than replacing every leather piece immediately. Keep a separate healing set if you intend to cover dungeon healing."},{t="anchor",id="talents"},{t="kicker",x=S[485]},{t="h2",x=S[539]},{t="p",x="Tree order: Elemental / Enhancement / Restoration. These 51 points are entered on the Standards.gg talent calculator and checked against the launch talent trees for totals, maximum ranks, tier gates and prerequisites. Changes made inside the calculator do not rewrite this guide. Start with 5/5 Tidal Focus and 3/3 Mindfulness for mana while you level. Once you have enough gear, move those points into 3/3 Call of Flame and 2/2 Trial by Fire, keeping 2/5 Tidal Focus (one more point goes into Reverberation to unlock Trial by Fire): ."},{t="widget",w="talents"},{t="h4",s="summary",x=S[541]},{t="widget",w="ranks"},{t="p",s="notice",x="This build is 11 / 32 / 8: it takes Spirit Weapons but not Improved Ghost Wolf, Water Shield or Lightning Mastery, favoring melee damage and mana support over utility."},{t="anchor",id="stats"},{t="kicker",x=S[613]},{t="h2",x=S[509]},{t="p",x="Weapon damage per second is always your best stat. |cff71d5ffCollect Strength and attack power gear as you level.|r Enhancement mixes melee and spells, and |cff71d5ffMental Dexterity (33% / 66% / 100% of your Intellect as attack power)|r and Mental Quickness turn Intellect into attack power and spell damage, |cff71d5ffbut Intellect is secondary to Strength and attack power.|r"},{t="h3",x=S[734]},{t="stat",i=1,b=S[911],x="a slow two-hander"},{t="stat",i=2,b="Strength",x="attack power"},{t="stat",i=3,b="Intellect",x="attack power and spell damage through talents"},{t="stat",i=4,b="Stamina",x=""},{t="stat",i=5,b="Agility",x="crit and armor"},{t="p",s="small",x="Use slow two-handed weapons, around 3.3 speed or slower: Stormstrike and Windfury Weapon hit harder with slow weapons."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[911],x=""},{t="stat",i=2,b="Hit chance",x="to 8%, more helps your spells"},{t="stat",i=3,b="Expertise",x="to 6.5%"},{t="stat",i=4,b=S[703],x="also keeps Flurry up"},{t="stat",i=5,b="Strength",x=""},{t="stat",i=6,b="Intellect",x=""},{t="p",s="small",x="Hit above 8% still helps because many of your attacks are spells (spell cap 17%). |cff71d5ffFavor Strength and attack power; Intellect is secondary because Mental Dexterity gives less attack power.|r"},{t="p",s="notice",x="Melee hit cap: 8% for special attacks against raid bosses. Expertise removes dodge at 6.5% and parry at 14% (parry only matters from the front). The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[510]},{t="h2",x=S[550]},{t="p",x=S[81]},{t="h4",x="Prepare weapon, shield and space"},{t="p",x="Keep a suitable weapon imbue active and maintain Lightning Shield when its damage will be used. Windfury Weapon is an option once trained. Spirit Weapons is selected, so you gain its parry chance and lower melee threat. Let the tank establish control before committing burst."},{t="h4",x="Keep melee contact and use Stormstrike"},{t="p",x="Position behind a tanked target where practical. |cff71d5ffStormstrike hits for 100% weapon damage on an 8-second cooldown,|r so press it whenever it is ready, then spend its damage benefit with Lightning Bolt, Chain Lightning or Earth Shock as the situation warrants. Avoid chasing a fleeing enemy into another pack just to preserve a swing."},{t="h4",x="Spend Maelstrom on Lightning Bolt"},{t="p",x="Read the charges before casting. |cff71d5ffEvery stack takes 20% off the cast time and Mana cost at all ranks, so five stacks support an instant, mana-free Lightning Bolt; the rank only changes how often it procs (6, 7, 8, 9 or 10 times a minute at ranks 1 to 5).|r The documented effect is for Lightning Bolt; do not assume it grants instant heals or Chain Lightning. A hard cast in melee can cost swings and expose you to pushback."},{t="h4",x="Choose shocks and fire damage deliberately"},{t="p",x="Earth Shock supplies an interrupt as well as damage; reserve it for a dangerous cast when needed. Flame Shock needs enough target life to pay back. For a safe pack, place a fire totem and use Fire Nova around its location. Keep area damage away from controlled enemies."},{t="h4",x="Use burst and recovery before trouble"},{t="p",x="Activate Rage of the Farseer when you can stay in melee. Heal, cleanse or use a defensive utility totem when that prevents a death. Improved Stormstrike and Mindfulness help sustain, but do not justify pulling indefinitely with no mana reserve."},{t="abil",names={"Stormstrike",S[898],S[861],"Earth Shock","Fire Nova",S[595]}},{t="h3",x=S[646]},{t="p",x="Weapon damage matters to melee attacks. Compare Strength, Agility, attack power, useful hit, Intellect and adequate Stamina. Your selected Mental Dexterity and Mental Quickness make Intellect useful beyond the mana pool. Check the target and attack type before treating any hit value as a universal cap."},{t="p",x=S[64]},{t="h3",x=S[504]},{t="p",x=S[56]},{t="p",x=S[52]},{t="p",x=S[124]},{t="anchor",id="macros"},{t="kicker",x=S[614]},{t="h2",x=S[424]},{t="p",x=S[59]},{t="p",s="notice",x=S[40]},{t="macro",n=S[551],x=S[126],code=S[201]},{t="macro",n=S[583],x=S[120],code=S[175]},{t="macro",n=S[594],x=S[113],code=S[199]},{t="macro",n=S[704],x=S[122],code=S[266]},{t="macro",n=S[563],x=S[121],code=S[230]},{t="macro",n=S[564],x=S[155],code=S[207]},{t="macro",n=S[552],x=S[247],code=S[202]},{t="macro",n=S[542],x=S[158],code=S[179]},{t="macro",n=S[565],x=S[94],code=S[173]},{t="macro",n=S[505],x=S[129],code=S[267]},{t="macro",n=S[615],x=S[160],code=S[342]},{t="macro",n=S[469],x=S[115],code=S[225]},{t="macro",n="Stormstrike and auto-attack",x="Start melee swings on your living hostile target and attempt Stormstrike. Auto-attacks can begin even when Stormstrike is on cooldown; requires your selected talent.",code="#showtooltip Stormstrike\n/startattack [harm,nodead]\n/cast [harm,nodead] Stormstrike"},{t="macro",n=S[595],x="Activate your selected melee cooldown and start attacking your hostile target. Use it when you can remain in range.",code="#showtooltip Rage of the Farseer\n/startattack [harm,nodead]\n/cast Rage of the Farseer"},{t="macro",n="Refresh Lightning Shield",x="Refresh your damage shield. Your supplied build does not learn Water Shield, so that spell is not put on this button.",code="#showtooltip Lightning Shield\n/cast Lightning Shield"},{t="p",s="small",x=S[256]},{t="anchor",id="dungeons"},{t="kicker",x=S[705]},{t="h2",x=S[474]},{t="p",x=S[60]},{t="widget",w="rarity"},{t="p",s="notice",x=S[46]},{t="p",s="notice",x=S[74]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[511]},{t="h2",x=S[470]},{t="p",x=S[61]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[543]},{t="h2",x=S[453]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[512]},{t="h2",x=S[420]},{t="p",x=S[41]},{t="widget",w="quest"},{t="anchor",id=S[483]},{t="kicker",x=S[706]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[91]}}},{id="restoration",name="Restoration",token="RESTO",title="Restoration | WoW Forever Shaman Field Guide",nav={{id="overview",x=S[767]},{id="journey",x=S[560]},{id="talents",x=S[484]},{id="stats",x=S[608]},{id="combat",x=S[609]},{id="macros",x=S[610]},{id="dungeons",x=S[540]},{id="professions",x=S[561]},{id="crafting",x=S[549]},{id="questgear",x=S[531]},{id=S[483],x=S[702]}},asideNote=S[68],talentString="00000000000000000550000000000000005530003315513151",ranks={{tree="Enhancement",name=S[611],r=5,max=5},{tree="Enhancement",name=S[593],r=5,max=5},{tree="Restoration",name="Improved Healing Wave",r=5,max=5},{tree="Restoration",name="Tidal Focus",r=5,max=5},{tree="Restoration",name="Mindfulness",r=3,max=3},{tree="Restoration",name="Ancestral Healing",r=3,max=3},{tree="Restoration",name="Healing Focus",r=3,max=3},{tree="Restoration",name=S[819],r=1,max=1},{tree="Restoration",name="Tidal Mastery",r=5,max=5},{tree="Restoration",name="Restorative Totems",r=5,max=5},{tree="Restoration",name=S[707],r=1,max=1},{tree="Restoration",name="Healing Way",r=3,max=3},{tree="Restoration",name="Nature's Swiftness",r=1,max=1},{tree="Restoration",name="Purification",r=5,max=5},{tree="Restoration",name="Riptide",r=1,max=1}},order={},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[532]},{t="h1",x="Restoration",sub=S[612]},{t="p",s="lede",x="Keep the party stable with efficient single-target heals, Riptide and well-aimed Chain Heals, supported by Water Shield, Mana Tide and encounter-specific totems."},{t="pills",list={S[699],S[562]}},{t="anchor",id="journey"},{t="kicker",x=S[768]},{t="h2",x=S[452]},{t="p",x=S[66]},{t="p",s="level",x="1–19 · Learn healing judgment"},{t="p",x="For a group-focused route, begin with Restoration healing and efficiency talents. Heal missing health rather than casting continuously at full-health targets. Outside a group, use trained Lightning Bolt and melee carefully; this healing endpoint is not a promise of fast solo damage."},{t="p",s="level",x="20–39 · Build reliable recovery"},{t="p",x="Develop Water Shield, casting protection and mana support as their talent gates open. Use Healing Wave when time allows and Lesser Healing Wave for faster responses. Learn the poison and disease tools available at your level. Keep line of sight to the tank and drink before the next pull."},{t="p",s="level",x="40–60 · Add group healing depth"},{t="p",x="Chain Heal becomes available at 40; obtain Riptide through your chosen talents and combine them when group damage justifies it. Finish the Restoration investment, then the selected ten Enhancement points for critical chance and Intellect. Keep a damage set for solo errands if useful."},{t="anchor",id="talents"},{t="kicker",x=S[485]},{t="h2",x=S[699]},{t="p",x="Tree order: Elemental / Enhancement / Restoration. These 51 points and selected ranks were checked against your supplied Standards.gg build. The link below is preloaded; changes made inside the calculator do not automatically rewrite this guide."},{t="widget",w="talents"},{t="h4",s="summary",x=S[541]},{t="widget",w="ranks"},{t="p",s="notice",x="This 0/10/41 allocation includes the main Restoration actives and full Healing Focus. It spends no points on Natural Grace, Totemic Focus or Improved Reincarnation. Plan threat, totem mana costs and recovery around those omissions."},{t="anchor",id="stats"},{t="kicker",x=S[613]},{t="h2",x=S[509]},{t="p",x="Restoration wants healing power first, then the mana stats that keep you casting. Critical strike adds burst healing."},{t="h3",x=S[734]},{t="stat",i=1,b=S[912],x="or spell power"},{t="stat",i=2,b="Intellect",x=S[793]},{t="stat",i=3,b="Spirit",x=S[588]},{t="stat",i=4,b="Stamina",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="p",s="small",x="When you quest alone, spell damage and Intellect also speed up kills. Keep a healing set for dungeons."},{t="h3",x="At level 60"},{t="stat",i=1,b=S[912],x=""},{t="stat",i=2,b=S[703],x=""},{t="stat",i=3,b="Intellect",x=""},{t="stat",i=4,b="Spirit",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="p",s="small",x="Healers do not need hit for heals. Balance healing power against mana stats depending on how long fights last."},{t="p",s="notice",x="Mana per 5 keeps working while you cast; Spirit regeneration stops for 5 seconds after each spell that costs mana. The level 60 list is an early estimate: the beta stopped at level 30, so expect changes once endgame gear is known. A big upgrade in a lower stat can still beat a small one in a higher stat."},{t="anchor",id="combat"},{t="kicker",x=S[510]},{t="h2",x=S[550]},{t="p",x=S[81]},{t="h4",x="Prepare Water Shield and positioning"},{t="p",x="Maintain Water Shield once learned, checking its charges during recovery windows. It shares the elemental-shield slot with Lightning Shield. Stand where you can see the tank and reach likely damage targets, while avoiding cleaves and unnecessary movement."},{t="h4",x="Choose a heal that lands in time"},{t="p",x="Use Healing Wave for a suitable cast window and Lesser Healing Wave when a faster heal is necessary. Match the heal to expected damage and missing health; overhealing wastes mana. Rank choice should follow the current tooltip, cost and outcome rather than a blanket lowest-rank rule."},{t="h4",x="Keep Riptide rolling"},{t="p",x="Riptide is a cheap heal over time with no up-front healing, on a 12-second cooldown. Cast it on cooldown on the most injured ally, ideally the target you will Chain Heal next, because Chain Heal heals a Riptide target for 25% more. For immediate healing, use Healing Wave, or Nature’s Swiftness in an emergency."},{t="h4",x="Aim Chain Heal at an injured cluster"},{t="p",x="Start on an appropriate injured target with nearby allies who also need healing. A spread group may get more value from individual heals. Check actual bounce positioning rather than assuming three useful targets. Avoid spending Chain Heal mana just to fill a small amount of missing health."},{t="h4",x="Time emergency tools and mana support"},{t="p",x="Use Nature’s Swiftness with a suitable Nature heal when a normal cast will be too late. Use Mana Tide while its recovery can be useful to the party and before you have no options left. Coordinate totems, cleanse harmful poison or disease, and communicate when the group must pause."},{t="abil",names={"Healing Wave","Lesser Healing Wave","Riptide","Chain Heal",S[819],S[707]}},{t="h3",x=S[646]},{t="p",x="Compare healing power, Intellect, useful mana regeneration and enough Stamina for the encounter. Spell-damage-only gear is not healing gear. Cloth or leather can be reasonable alternatives to mail when their healing stats are stronger, but assess the defensive loss. Weapon damage does not improve heals."},{t="p",x=S[64]},{t="h3",x=S[504]},{t="p",x=S[56]},{t="p",x=S[52]},{t="p",x=S[124]},{t="anchor",id="macros"},{t="kicker",x=S[614]},{t="h2",x=S[424]},{t="p",x=S[59]},{t="p",s="notice",x=S[40]},{t="macro",n=S[551],x=S[126],code=S[201]},{t="macro",n=S[583],x=S[120],code=S[175]},{t="macro",n=S[594],x=S[113],code=S[199]},{t="macro",n=S[704],x=S[122],code=S[266]},{t="macro",n=S[563],x=S[121],code=S[230]},{t="macro",n=S[564],x=S[155],code=S[207]},{t="macro",n=S[552],x=S[247],code=S[202]},{t="macro",n=S[542],x=S[158],code=S[179]},{t="macro",n=S[565],x=S[94],code=S[173]},{t="macro",n=S[505],x=S[129],code=S[267]},{t="macro",n=S[615],x=S[160],code=S[342]},{t="macro",n=S[469],x=S[115],code=S[225]},{t="macro",n="Mouseover Chain Heal",x="Start the chain on the hovered ally, friendly target or yourself. Choose the first recipient and let the normal bounce rules determine later recipients.",code="#showtooltip Chain Heal\n/cast [@mouseover,help,nodead][help,nodead][@player] Chain Heal"},{t="macro",n="Mouseover Riptide",x="Apply your selected instant heal to a living friendly mouseover, friendly target or yourself. Use only after learning the talent.",code="#showtooltip Riptide\n/cast [@mouseover,help,nodead][help,nodead][@player] Riptide"},{t="macro",n="Emergency instant Healing Wave",x="Stops your current cast, activates your selected Nature’s Swiftness, then attempts Healing Wave. It still needs a valid recipient and sufficient mana; if the cooldown is unavailable it can begin a normal cast.",code="#showtooltip Nature's Swiftness\n/stopcasting\n/cast Nature's Swiftness\n/cast [@mouseover,help,nodead][help,nodead][@player] Healing Wave"},{t="macro",n="Refresh Water Shield",x="Reapply your selected mana shield when useful. Replaces Lightning Shield because only one elemental shield can be active.",code="#showtooltip Water Shield\n/cast Water Shield"},{t="macro",n=S[707],x="Place your selected mana-recovery totem when the party can benefit. Keep it separate from routine totem presets so you do not spend the cooldown accidentally.",code="#showtooltip Mana Tide Totem\n/cast Mana Tide Totem"},{t="p",s="small",x=S[256]},{t="anchor",id="dungeons"},{t="kicker",x=S[705]},{t="h2",x=S[474]},{t="p",x=S[60]},{t="widget",w="rarity"},{t="p",s="notice",x=S[46]},{t="p",s="notice",x=S[74]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[511]},{t="h2",x=S[470]},{t="p",x=S[61]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[543]},{t="h2",x=S[453]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[512]},{t="h2",x=S[420]},{t="p",x=S[41]},{t="widget",w="quest"},{t="anchor",id=S[